1	package v1
2	
3	import (
4		"fmt"
5		"regexp"
6		"time"
7	
8		"github.com/pkg/errors"
9		"google.golang.org/protobuf/types/known/timestamppb"
10	
11		v1pb "github.com/usememos/memos/proto/gen/api/v1"
12		storepb "github.com/usememos/memos/proto/gen/store"
13		"github.com/usememos/memos/store"
14	)
15	
16	func convertUserFromStore(user *store.User, viewer *store.User) *v1pb.User {
17		userpb := &v1pb.User{
18			Name:        BuildUserName(user.Username),
19			State:       convertStateFromStore(user.RowStatus),
20			CreateTime:  timestamppb.New(time.Unix(user.CreatedTs, 0)),
21			UpdateTime:  timestamppb.New(time.Unix(user.UpdatedTs, 0)),
22			Role:        convertUserRoleFromStore(user.Role),
23			Username:    user.Username,
24			DisplayName: user.Nickname,
25			AvatarUrl:   user.AvatarURL,
26			Description: user.Description,
27		}
28		if canViewerAccessUserEmail(viewer, user) {
29			userpb.Email = user.Email
30		}
31		// Use the avatar URL instead of raw base64 image data to reduce the response size.
32		if user.AvatarURL != "" {
33			// Check if avatar url is base64 format.
34			_, _, err := extractImageInfo(user.AvatarURL)
35			if err == nil {
36				userpb.AvatarUrl = fmt.Sprintf("/file/%s/avatar", userpb.Name)
37			} else {
38				userpb.AvatarUrl = user.AvatarURL
39			}
40		}
41		return userpb
42	}
43	
44	func canViewerAccessUserEmail(viewer, user *store.User) bool {
45		if viewer == nil || user == nil {
46			return false
47		}
48		return viewer.Role == store.RoleAdmin || viewer.ID == user.ID
49	}
50	
51	func convertUserRoleFromStore(role store.Role) v1pb.User_Role {
52		switch role {
53		case store.RoleAdmin:
54			return v1pb.User_ADMIN
55		case store.RoleUser:
56			return v1pb.User_USER
57		default:
58			return v1pb.User_ROLE_UNSPECIFIED
59		}
60	}
61	
62	func convertUserRoleToStore(role v1pb.User_Role) store.Role {
63		switch role {
64		case v1pb.User_ADMIN:
65			return store.RoleAdmin
66		default:
67			return store.RoleUser
68		}
69	}
70	
71	// extractImageInfo extracts image type and base64 data from a data URI.
72	// Data URI format: data:image/png;base64,iVBORw0KGgo...
73	func extractImageInfo(dataURI string) (string, string, error) {
74		dataURIRegex := regexp.MustCompile(`^data:(?P<type>.+);base64,(?P<base64>.+)`)
75		matches := dataURIRegex.FindStringSubmatch(dataURI)
76		if len(matches) != 3 {
77			return "", "", errors.New("invalid data URI format")
78		}
79		imageType := matches[1]
80		base64Data := matches[2]
81		return imageType, base64Data, nil
82	}
83	
84	// convertSettingKeyToStore converts API setting key to store enum.
85	func convertSettingKeyToStore(key string) (storepb.UserSetting_Key, error) {
86		switch key {
87		case v1pb.UserSetting_Key_name[int32(v1pb.UserSetting_GENERAL)]:
88			return storepb.UserSetting_GENERAL, nil
89		case v1pb.UserSetting_Key_name[int32(v1pb.UserSetting_WEBHOOKS)]:
90			return storepb.UserSetting_WEBHOOKS, nil
91		case v1pb.UserSetting_Key_name[int32(v1pb.UserSetting_TAGS)]:
92			return storepb.UserSetting_TAGS, nil
93		default:
94			return storepb.UserSetting_KEY_UNSPECIFIED, errors.Errorf("unknown setting key: %s", key)
95		}
96	}
97	
98	// convertSettingKeyFromStore converts store enum to API setting key.
99	func convertSettingKeyFromStore(key storepb.UserSetting_Key) string {
100		switch key {
101		case storepb.UserSetting_GENERAL:
102			return v1pb.UserSetting_Key_name[int32(v1pb.UserSetting_GENERAL)]
103		case storepb.UserSetting_SHORTCUTS:
104			return "SHORTCUTS" // Not defined in API proto
105		case storepb.UserSetting_WEBHOOKS:
106			return v1pb.UserSetting_Key_name[int32(v1pb.UserSetting_WEBHOOKS)]
107		case storepb.UserSetting_TAGS:
108			return v1pb.UserSetting_Key_name[int32(v1pb.UserSetting_TAGS)]
109		default:
